(()=>{'use strict';const API='https://woongbi-quote-api.woongbts.workers.dev/quote/mobile';const ids=['carrier','join-type','discount-method','device-select','plan-select','installment-months','welfare-type'];let timer=0,seq=0,applying=false;const cache=new Map();const $=id=>document.getElementById(id);const won=v=>Number.isFinite(Number(v))?Math.max(0,Math.round(Number(v))).toLocaleString('ko-KR')+'원':'—';const text=(id,value)=>{const el=$(id);if(el&&el.textContent!==String(value))el.textContent=String(value)};function state(){const device=$('device-select')?.value||'',plan=$('plan-select')?.value||'',join=$('join-type')?.value||'',method=$('discount-method')?.value||'support',months=Number($('installment-months')?.value||24),welfare=$('welfare-type')?.value||'none';return{device,plan,join,method,months,welfare,key:[device,plan,join,months,welfare].join('|')}}async function requestQuote(s,method){const key=s.key+'|'+method;if(cache.has(key))return cache.get(key);const res=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({device_id:s.device,plan_id:s.plan,join_type:s.join,method,months:s.months,welfare_type:s.welfare})});if(!res.ok)throw Error('quote-api-'+res.status);const data=await res.json();if(!data||data.ok!==true)throw Error('quote-api-invalid');cache.set(key,data.quote);if(cache.size>40)cache.delete(cache.keys().next().value);return data.quote}function applyCurrent(q,s){if(!q?.known)return;text('device-price-view',won(q.price));text('plan-fee-view',won(q.planFee));if(s.method==='contract'){text('discount-amount-view','-'+won(q.contractDiscount));text('plan-discount-view','-'+won(q.contractDiscount))}else{text('discount-amount-view',won(q.support));text('plan-discount-view','미적용')}text('principal',won(q.principal));text('device-monthly',won(q.inst?.monthly));text('installment-fee',won(q.inst?.fee));text('service-monthly',won(q.service));text('monthly-total',won(q.monthly));text('mobile-quote-bar-total',won(q.monthly));text('welfare-view',q.welfare?.amount?`${q.welfare.label||'복지할인'} -${won(q.welfare.amount)}`:'미적용');text('explain-price',won(q.price));text('explain-device-discount',s.method==='support'&&q.support?'-'+won(q.support):'미적용');text('explain-principal',won(q.principal));text('explain-interest',won(q.inst?.fee));text('explain-device-monthly',won(q.inst?.monthly));text('explain-plan-fee',won(q.planFee));text('explain-contract-discount',s.method==='contract'&&q.contractDiscount?'-'+won(q.contractDiscount):'미적용');text('explain-welfare',q.welfare?.amount?'-'+won(q.welfare.amount):'미적용');text('explain-service',won(q.service));text('explain-monthly-total',won(q.monthly));text('explain-note',`월 단말금 ${won(q.inst?.monthly)} + 월 통신요금 ${won(q.service)} = 예상 월 납부액 ${won(q.monthly)}입니다. 추가지원금·실시간 프로모션은 포함하지 않습니다.`)}function applyCompare(support,contract){if(support?.known){text('compare-support-monthly',won(support.monthly));text('compare-support-benefit',`공시지원금 ${won(support.support)}`)}else if(support&&support.known===false){text('compare-support-monthly','매장 확인');text('compare-support-benefit','지원금 —')}if(contract?.known){text('compare-contract-monthly',won(contract.monthly));text('compare-contract-benefit',`월 선택약정 할인 ${won(contract.contractDiscount)}`)}if(support?.known&&contract?.known){const diff=Math.abs(Number(support.total24)-Number(contract.total24));const best=Number(support.total24)<=Number(contract.total24)?'공시지원금':'선택약정';text('compare-best',diff<500?'두 방식이 비슷해요':`${best} 쪽이 유리`);text('compare-diff',diff<500?'현재 조건에서는 두 방식의 전체 부담 차이가 크지 않습니다.':`${best} 쪽이 전체 부담 기준으로 더 유리합니다.`)}else if(contract?.known&&support&&support.known===false){text('compare-best','공시지원금 확인 필요');text('compare-diff','선택약정은 계산됐고, 공시지원금은 매장에서 최신 금액을 확인해 비교해 드립니다.')}}async function sync(){const s=state();if(!s.device||!s.plan||!s.join)return;const run=++seq;try{const [a,b]=await Promise.allSettled([requestQuote(s,'support'),requestQuote(s,'contract')]);if(run!==seq)return;const support=a.status==='fulfilled'?a.value:null,contract=b.status==='fulfilled'?b.value:null;applying=true;applyCompare(support,contract);applyCurrent(s.method==='contract'?contract:support,s);document.documentElement.dataset.quoteApi='ready'}catch{document.documentElement.dataset.quoteApi='fallback'}finally{applying=false}}function schedule(){clearTimeout(timer);timer=setTimeout(sync,90)}function init(){if(!$('device-select')||!$('plan-select'))return;ids.forEach(id=>$(id)?.addEventListener('change',schedule));$('device-search')?.addEventListener('input',schedule);const target=$('monthly-total');if(target)new MutationObserver(()=>{if(!applying)schedule()}).observe(target,{childList:true,characterData:true,subtree:true});schedule()}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init()})();
